
(()=>{
 const reduced=matchMedia('(prefers-reduced-motion: reduce)'),mobile=matchMedia('(max-width:800px)');
 const header=document.querySelector('.header'),menu=header.querySelector('.menu-button'),nav=header.querySelector('nav');
 const scrim=document.createElement('button');scrim.className='menu-scrim';scrim.tabIndex=-1;scrim.type='button';scrim.setAttribute('aria-label','Cerrar menú');header.after(scrim);
 function setMenu(open,restore=false){header.classList.toggle('is-open',open);document.body.classList.toggle('menu-open',open&&mobile.matches);menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Cerrar −':'Menú +';nav.inert=mobile.matches&&!open;if(open)setTimeout(()=>{if(header.classList.contains('is-open'))nav.querySelector('a').focus({preventScroll:true})},reduced.matches?0:280);else if(restore)menu.focus({preventScroll:true})}
 nav.inert=mobile.matches;menu.addEventListener('click',()=>setMenu(!header.classList.contains('is-open')));scrim.addEventListener('click',()=>setMenu(false,true));nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>setMenu(false)));mobile.addEventListener('change',()=>setMenu(false));
 document.addEventListener('keydown',e=>{if(!header.classList.contains('is-open'))return;if(e.key==='Escape'){e.preventDefault();setMenu(false,true)}if(e.key==='Tab'){const items=[menu,...nav.querySelectorAll('a')],first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
 document.querySelector('.contact form')?.addEventListener('submit',e=>{e.preventDefault();e.target.querySelector('.form-status').textContent='Vista de diseño: el envío aún no está conectado. No se ha enviado ningún mensaje.'});
 const home=!!document.querySelector('.hero'),navType=performance.getEntriesByType('navigation')[0]?.type;
 if(home&&!reduced.matches&&navType!=='back_forward'&&!location.hash){document.documentElement.classList.add('cover-ready');setTimeout(()=>document.documentElement.classList.remove('cover-ready'),1600)}
 const vt=CSS.supports('view-transition-name','qraft-image')&&!reduced.matches;
 if(vt){document.querySelectorAll('.work-cover-link,.work-card').forEach(a=>{a.querySelector('img').style.viewTransitionName='work-'+a.getAttribute('href').replace('.html','')});const first=document.querySelector('.project-page .gallery img');if(first)first.style.viewTransitionName='work-'+location.pathname.split('/').at(-1).replace('.html','');document.querySelector('.cover-picture')?.addEventListener('click',()=>{const link=document.querySelector('.cover-picture'),href=link.getAttribute('href');document.querySelector('.work-cover-link[href="'+href+'"] img,.work-card[href="'+href+'"] img').style.viewTransitionName='none';link.querySelector('img.is-current').style.viewTransitionName='work-'+href.replace('.html','')})}
 if(home){document.querySelectorAll('a[href$=".html"]').forEach(a=>a.addEventListener('click',()=>{try{sessionStorage.setItem('qraft17-scroll',String(scrollY))}catch{}}));addEventListener('pageshow',e=>{if(e.persisted||navType==='back_forward'){document.documentElement.classList.remove('cover-ready');if(vt){document.querySelectorAll('.cover-picture img').forEach(img=>img.style.viewTransitionName='none');document.querySelectorAll('.work-cover-link,.work-card').forEach(a=>a.querySelector('img').style.viewTransitionName='work-'+a.getAttribute('href').replace('.html',''))}try{const y=Number(sessionStorage.getItem('qraft17-scroll'));if(y)requestAnimationFrame(()=>scrollTo({top:y,behavior:'instant'}))}catch{}}});if('IntersectionObserver'in window){const observer=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting)nav.querySelectorAll('a').forEach(a=>{if(a.getAttribute('href')==='#'+e.target.id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current')})}),{rootMargin:'-15% 0px -65%'});document.querySelectorAll('section[id]').forEach(el=>observer.observe(el))}}
})();
